mapper.select:
SELECT EXISTS (
    SELECT 1 FROM public.team_invitations
    WHERE team_id = #{teamId}
      AND invited_email = #{invitedEmail}
      AND status = 'PENDING'
)

mapper.update:
UPDATE public.team_invitations
SET status     = #{status},
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE public.team_invitations
SET status      = 'ACCEPTED',
    accepted_at = #{acceptedAt},
    updated_at  = #{updatedAt}
WHERE id = #{id}

UPDATE public.team_invitations
SET status     = 'EXPIRED',
    updated_at = #{updatedAt}
WHERE status = 'PENDING'
  AND expires_at < #{now}
